describe('createPreviewApiHandler()', () => {
	let tmpDir: string;
	let prevCwd: string;

	beforeEach(async () => {
		prevCwd = process.cwd();
		tmpDir = await mkdtemp(path.join(tmpdir(), 'bse-cli-preview-api-'));
		process.chdir(tmpDir);
		await mkdir(path.join(tmpDir, 'nested'), { recursive: true });
		await writeFile(path.join(tmpDir, 'Welcome.svelte'), '<script></script>\n', 'utf8');
		await writeFile(path.join(tmpDir, 'nested', 'Foo.svelte'), '<script></script>\n', 'utf8');
	});

	afterEach(async () => {
		process.chdir(prevCwd);
		await rm(tmpDir, { recursive: true, force: true });
	});

	it('GET /api/emails returns sorted relative paths', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/emails' });
		const { res, status, json } = collectResponse();
		const handled = await handlePreviewApi(new URL('http://127.0.0.1/api/emails'), req, res);
		expect(handled).toBe(true);
		expect(status()).toBe(200);
		const payload = json() as { files: string[]; path: string };
		expect(payload.files).toEqual(['Welcome', 'nested/Foo']);
		expect(payload.path).toBe('.');
	});

	it('GET /api/source returns file contents', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/source?file=Welcome' });
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/source?file=Welcome'), req, res);
		expect(status()).toBe(200);
		const payload = json() as { file: string; source: string };
		expect(payload.file).toBe('Welcome');
		expect(payload.source).toContain('<script>');
	});

	it('GET /api/source rejects path traversal', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/source?file=../Welcome' });
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/source?file=../Welcome'), req, res);
		expect(status()).toBe(400);
		expect((json() as { error: { message: string } }).error.message).toContain('invalid');
	});

	it('GET /api/source returns 404 for missing file', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/source?file=Missing' });
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/source?file=Missing'), req, res);
		expect(status()).toBe(404);
		expect((json() as { error: { message: string } }).error.message).toContain('not found');
	});

	it('POST /api/render returns 404 when file is missing (before Vite)', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({
			method: 'POST',
			url: '/api/render',
			body: JSON.stringify({ file: 'Nope' })
		});
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/render'), req, res);
		expect(status()).toBe(404);
		expect((json() as { error: { message: string } }).error.message).toContain('not found');
	});

	it('POST /api/render rejects invalid JSON body', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({
			method: 'POST',
			url: '/api/render',
			body: 'not-json'
		});
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/render'), req, res);
		expect(status()).toBe(400);
		expect((json() as { error: { message: string } }).error.message).toContain('JSON');
	});

	it('returns false for non-API paths', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/' });
		const { res, status, raw } = collectResponse();
		const handled = await handlePreviewApi(new URL('http://127.0.0.1/'), req, res);
		expect(handled).toBe(false);
		expect(status()).toBe(0);
		expect(raw()).toBe('');
	});

	it('unknown API route returns 404 JSON', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/unknown' });
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/unknown'), req, res);
		expect(status()).toBe(404);
		expect((json() as { error: { message: string } }).error.message).toContain('not found');
	});

	it('GET /api/send-email/config reports unconfigured by default', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({ method: 'GET', url: '/api/send-email/config' });
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/send-email/config'), req, res);
		expect(status()).toBe(200);
		expect(json()).toEqual({ configured: false, from: null, persisted: false });
	});

	it('POST /api/send-email/config stores session credentials without persisting', async () => {
		const store = createResendCredentialsStore(tmpDir);
		const { handlePreviewApi } = createPreviewApiHandler({
			emailsDir: '.',
			resendCredentials: store
		});
		const req = makeRequest({
			method: 'POST',
			url: '/api/send-email/config',
			body: JSON.stringify({
				apiKey: 're_test',
				from: 'onboarding@resend.dev',
				persist: false
			})
		});
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/send-email/config'), req, res);
		expect(status()).toBe(200);
		expect((json() as { configured: boolean }).configured).toBe(true);
		expect(store.get()?.apiKey).toBe('re_test');
	});

	it('POST /api/send-email rejects when not configured', async () => {
		const { handlePreviewApi } = createTestPreviewApiHandler('.');
		const req = makeRequest({
			method: 'POST',
			url: '/api/send-email',
			body: JSON.stringify({
				to: 'user@example.com',
				file: 'Welcome',
				html: '<p>Hi</p>'
			})
		});
		const { res, status, json } = collectResponse();
		await handlePreviewApi(new URL('http://127.0.0.1/api/send-email'), req, res);
		expect(status()).toBe(400);
		expect((json() as { error: { message: string } }).error.message).toContain('not configured');
	});
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import { readFile } from 'node:fs/promises';

const getExportKeys = (exportsObject: Record<string, unknown>) => Object.keys(exportsObject).sort();

describe('better-svelte-email exports', () => {
	afterEach(() => {
		vi.clearAllMocks();
		vi.resetModules();
	});

	describe('folder index exports', () => {
		it('re-exports all component exports from components/', async () => {
			const componentA = Symbol('Body');
			const componentB = Symbol('Button');
			const mockedComponentPackage = { Body: componentA, Button: componentB };

			vi.doMock('@better-svelte-email/components', () => mockedComponentPackage);

			const componentsExports = await import('./components');

			expect(getExportKeys(componentsExports)).toEqual(getExportKeys(mockedComponentPackage));
			expect(componentsExports.Body).toBe(componentA);
			expect(componentsExports.Button).toBe(componentB);
		});

		it('re-exports all preview exports from preview/', async () => {
			const source = await readFile(new URL('./preview/index.ts', import.meta.url), 'utf8');

			expect(source).toContain("export * from '@better-svelte-email/preview';");
			expect(source).toContain(
				"export { default as EmailPreview } from '@better-svelte-email/preview/EmailPreview.svelte';"
			);
		});

		it('re-exports the intended public render API from render/', async () => {
			class MockedRenderer {}
			const mockedToPlainText = vi.fn();

			vi.doMock('@better-svelte-email/server', () => ({
				Renderer: MockedRenderer,
				toPlainText: mockedToPlainText,
				pixelBasedPreset: { test: true }
			}));

			const renderExports = await import('./render');

			expect(getExportKeys(renderExports)).toEqual(['default', 'toPlainText']);
			expect(renderExports.default).toBe(MockedRenderer);
			expect(renderExports.toPlainText).toBe(mockedToPlainText);
			expect('pixelBasedPreset' in renderExports).toBe(false);
		});

		it('re-exports all utility exports from utils/', async () => {
			const styleToString = vi.fn();
			const withMargin = vi.fn();
			const mockedUtilsPackage = { styleToString, withMargin };

			vi.doMock('@better-svelte-email/components/utils', () => mockedUtilsPackage);

			const utilsExports = await import('./utils');

			expect(getExportKeys(utilsExports)).toEqual(getExportKeys(mockedUtilsPackage));
			expect(utilsExports.styleToString).toBe(styleToString);
			expect(utilsExports.withMargin).toBe(withMargin);
		});
	});

	describe('root index exports', () => {
		it('exports components plus render aliases from src/index.ts', async () => {
			const body = Symbol('Body');
			const button = Symbol('Button');
			class MockedRenderer {}
			const mockedToPlainText = vi.fn();

			vi.doMock('./preview', () => ({}));
			vi.doMock('./utils', () => ({}));
			vi.doMock('./components', () => ({
				Body: body,
				Button: button
			}));
			vi.doMock('./render', () => ({
				default: MockedRenderer,
				toPlainText: mockedToPlainText
			}));

			const rootExports = await import('./index');
			const componentsExports = await import('./components');
			const renderExports = await import('./render');

			const expectedRootKeys = [
				...getExportKeys(componentsExports),
				'Renderer',
				'toPlainText'
			].sort();
			expect(getExportKeys(rootExports)).toEqual(expectedRootKeys);
			expect(rootExports.Renderer).toBe(renderExports.default);
			expect(rootExports.toPlainText).toBe(renderExports.toPlainText);
		});
	});
});

import { describe, expect, it } from 'vitest';
import { buildEmailTree, filterEmailTree } from './email-tree';

describe('buildEmailTree()', () => {
	it('returns an empty array for null, undefined, or empty input', () => {
		expect(buildEmailTree(null)).toEqual([]);
		expect(buildEmailTree(undefined)).toEqual([]);
		expect(buildEmailTree([])).toEqual([]);
	});

	it('builds a nested tree and sorts directories before files', () => {
		const tree = buildEmailTree(['a/File.svelte', 'b/File.svelte', 'Root.svelte']);
		expect(tree.map((n) => n.name)).toEqual(['a', 'b', 'Root.svelte']);
		const dirA = tree.find((n) => n.type === 'directory' && n.name === 'a');
		expect(dirA?.type).toBe('directory');
		if (dirA?.type === 'directory') {
			expect(dirA.items).toHaveLength(1);
			expect(dirA.items[0]).toMatchObject({
				type: 'file',
				name: 'File.svelte',
				path: 'a/File.svelte'
			});
		}
	});

	it('normalizes leading dots and slashes', () => {
		const tree = buildEmailTree(['./foo//Bar.svelte']);
		expect(tree).toHaveLength(1);
		expect(tree[0]).toMatchObject({
			type: 'directory',
			name: 'foo',
			path: 'foo'
		});
		if (tree[0].type === 'directory') {
			expect(tree[0].items[0]).toMatchObject({
				type: 'file',
				name: 'Bar.svelte',
				path: 'foo/Bar.svelte'
			});
		}
	});

	it('skips empty string paths', () => {
		expect(buildEmailTree([''])).toEqual([]);
	});
});

describe('filterEmailTree()', () => {
	const sample = buildEmailTree(['news/Weekly.svelte', 'Welcome.svelte']);

	it('returns a shallow copy when query is empty', () => {
		const filtered = filterEmailTree(sample, '');
		expect(filtered).toEqual(sample);
		expect(filtered).not.toBe(sample);
	});

	it('matches file paths case-insensitively', () => {
		const filtered = filterEmailTree(sample, 'WEEKLY');
		expect(filtered).toHaveLength(1);
		expect(filtered[0].type).toBe('directory');
		if (filtered[0].type === 'directory') {
			expect(filtered[0].items).toHaveLength(1);
			expect(filtered[0].items[0]).toMatchObject({ path: 'news/Weekly.svelte' });
		}
	});

	it('keeps parent directory when a child matches', () => {
		const filtered = filterEmailTree(sample, 'Weekly');
		expect(filtered.some((n) => n.type === 'directory' && n.name === 'news')).toBe(true);
	});

	it('returns empty array when nothing matches', () => {
		expect(filterEmailTree(sample, 'xyz-none')).toEqual([]);
	});
});

